```rust
use std::sync::{Arc, Mutex};
use std::thread;

fn compute() -> i32 {
    let tmp = 1;
    tmp
}

fn w1(m: Arc<Mutex<i32>>) {
    let mut guard = m.lock().unwrap();
    let _tmp = compute();
    *guard = *guard + 1;
    drop(guard);
}

fn w2(m: Arc<Mutex<i32>>) {
    let mut guard = m.lock().unwrap();
    let _tmp = compute();
    *guard = *guard + 1;
    drop(guard);
}

fn main() {
    let m = Arc::new(Mutex::new(0i32));

    let m1 = Arc::clone(&m);
    let m2 = Arc::clone(&m);

    let t1 = thread::spawn(move || w1(m1));
    let t2 = thread::spawn(move || w2(m2));

    t1.join().unwrap();
    t2.join().unwrap();

    println!("DONE done=1");
}
